/*
 STUDENT DATA ETL - n8n
 Supports:
 1. Excel Extract From File output
 2. Basic LLM Chain JSON text output

 Operations:
 - Parse JSON
 - Clean text and numbers
 - Normalize dates and phone numbers
 - Validate mandatory fields
 - Detect duplicates
 - Classify VALID / INVALID
 - Produce error details
*/

const items = $input.all();

const seenIds = new Set();
const seenEmails = new Set();

const validCourses = [
  "Mathematics",
  "Physics",
  "Business",
  "Biology",
  "Computer Science"
];

const validStatuses = ["Active", "Inactive"];

// --------------------------------------------------
// 1. PARSE INPUT
// --------------------------------------------------

function parseInput(item) {
  const data = item.json;

  if (typeof data.text !== "string") {
    return data;
  }

  let text = data.text.trim();

  // Remove optional Markdown code fences
  text = text
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  const parsed = JSON.parse(text);

  if (
    !parsed ||
    typeof parsed !== "object" ||
    Array.isArray(parsed)
  ) {
    throw new Error("Expected one student JSON object");
  }

  return parsed;
}

// --------------------------------------------------
// 2. CLEANING FUNCTIONS
// --------------------------------------------------

function cleanText(value) {
  return String(value ?? "")
    .trim()
    .replace(/\s+/g, " ");
}

function titleCase(value) {
  return cleanText(value)
    .toLowerCase()
    .replace(/\b[a-z]/g, char => char.toUpperCase());
}

function cleanEmail(value) {
  return cleanText(value).toLowerCase();
}

function cleanPhone(value) {
  return cleanText(value).replace(/[\s().-]/g, "");
}

function cleanNumber(value) {
  const text = cleanText(value).replace(/%$/, "");

  if (!text || !/^[+-]?\d+(\.\d+)?$/.test(text)) {
    return null;
  }

  const number = Number(text);

  return Number.isFinite(number) ? number : null;
}

// --------------------------------------------------
// 3. DATE NORMALIZATION
// --------------------------------------------------

function cleanDate(value) {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  // Numeric Excel serial date
  if (typeof value === "number") {
    if (
      !Number.isInteger(value) ||
      value < 1 ||
      value > 2958465
    ) {
      return null;
    }

    const date = new Date(
      Date.UTC(1899, 11, 30) + value * 86400000
    );

    return date.toISOString().slice(0, 10);
  }

  const text = cleanText(value);

  let year, month, day;
  let match;

  // ISO: YYYY-MM-DD
  if (
    (match = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(text))
  ) {
    year = Number(match[1]);
    month = Number(match[2]);
    day = Number(match[3]);
  }

  // Slash date: DD/MM/YYYY or MM/DD/YYYY
  else if (
    (match = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(text))
  ) {
    const first = Number(match[1]);
    const second = Number(match[2]);

    year = Number(match[3]);

    if (first > 12) {
      day = first;
      month = second;
    } else if (second > 12) {
      month = first;
      day = second;
    } else {
      // Ambiguous: requires manual review
      return null;
    }
  }

  // DD-MM-YYYY
  else if (
    (match = /^(\d{1,2})-(\d{1,2})-(\d{4})$/.exec(text))
  ) {
    day = Number(match[1]);
    month = Number(match[2]);
    year = Number(match[3]);
  }

  else {
    return null;
  }

  const date = new Date(
    Date.UTC(year, month - 1, day)
  );

  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() + 1 !== month ||
    date.getUTCDate() !== day
  ) {
    return null;
  }

  return date.toISOString().slice(0, 10);
}

// --------------------------------------------------
// 4. MAIN ETL PROCESS
// --------------------------------------------------

const output = [];

for (let i = 0; i < items.length; i++) {

  const errors = [];
  let raw;

  // STEP 1: Parse Excel JSON or LLM JSON text
  try {
    raw = parseInput(items[i]);
  } catch (error) {
    output.push({
      json: {
        Source_Row: i + 2,
        Data_Quality: "INVALID",
        Error_Count: 1,
        Error_Details: "JSON parse error: " + error.message,
        Raw_Data: JSON.stringify(items[i].json)
      }
    });
    continue;
  }

  // STEP 2: Clean student fields
  const student = {
    Student_ID: cleanText(raw.Student_ID).toUpperCase(),
    Full_Name: titleCase(raw.Full_Name),
    Email: cleanEmail(raw.Email),
    Phone: cleanPhone(raw.Phone),
    Date_of_Birth: cleanDate(raw.Date_of_Birth),
    Enrollment_Date: cleanDate(raw.Enrollment_Date),
    Course: titleCase(raw.Course),
    Score: cleanNumber(raw.Score),
    Attendance_Pct: cleanNumber(raw.Attendance_Pct),
    City: titleCase(raw.City),
    Status: titleCase(raw.Status)
  };

  // STEP 3: Validate Student ID
  if (!/^STU\d{4}$/.test(student.Student_ID)) {
    errors.push("Invalid or missing Student ID");
  }

  if (student.Student_ID) {
    if (seenIds.has(student.Student_ID)) {
      errors.push("Duplicate Student ID");
    }
    seenIds.add(student.Student_ID);
  }

  // STEP 4: Validate Full Name
  if (
    !student.Full_Name ||
    !/^[A-Za-z][A-Za-z .'-]*$/.test(student.Full_Name)
  ) {
    errors.push("Invalid or missing Full Name");
  }

  // STEP 5: Validate Email
  const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (!emailPattern.test(student.Email)) {
    errors.push("Invalid or missing Email");
  }

  if (student.Email) {
    if (seenEmails.has(student.Email)) {
      errors.push("Duplicate Email");
    }
    seenEmails.add(student.Email);
  }

  // STEP 6: Validate Phone
  if (!/^\+?\d{10,15}$/.test(student.Phone)) {
    errors.push("Invalid Phone");
  }

  // STEP 7: Validate Dates
  if (!student.Date_of_Birth) {
    errors.push("Invalid Date of Birth");
  }

  if (!student.Enrollment_Date) {
    errors.push("Invalid Enrollment Date");
  }

  const today = new Date().toISOString().slice(0, 10);

  if (
    student.Date_of_Birth &&
    student.Date_of_Birth > today
  ) {
    errors.push("Future Date of Birth");
  }

  if (
    student.Enrollment_Date &&
    student.Enrollment_Date > today
  ) {
    errors.push("Future Enrollment Date");
  }

  if (
    student.Date_of_Birth &&
    student.Enrollment_Date &&
    student.Enrollment_Date < student.Date_of_Birth
  ) {
    errors.push("Enrollment Before Date of Birth");
  }

  // STEP 8: Validate Course
  if (!validCourses.includes(student.Course)) {
    errors.push("Invalid Course");
  }

  // STEP 9: Validate Score
  if (
    student.Score === null ||
    student.Score < 0 ||
    student.Score > 100
  ) {
    errors.push("Invalid Score");
  }

  // STEP 10: Validate Attendance
  if (
    student.Attendance_Pct === null ||
    student.Attendance_Pct < 0 ||
    student.Attendance_Pct > 100
  ) {
    errors.push("Invalid Attendance");
  }

  // STEP 11: Validate City
  if (!student.City) {
    errors.push("Missing City");
  }

  // STEP 12: Validate Status
  if (!validStatuses.includes(student.Status)) {
    errors.push("Invalid Status");
  }

  // STEP 13: Classify data quality
  student.Data_Quality =
    errors.length === 0 ? "VALID" : "INVALID";

  student.Error_Count = errors.length;
  student.Error_Details = errors.join("; ");
  student.Source_Row = i + 2;

  output.push({
    json: student,
    pairedItem: { item: i }
  });
}

// --------------------------------------------------
// 5. RETURN CLEANED DATA
// --------------------------------------------------

return output;
